import React, { useEffect, useState, useCallback } from 'react';
import { useAuth } from '../context/AuthContext';
import { inventoryService } from '../services/api';
import toast from 'react-hot-toast';
import { Plus, AlertTriangle, Edit3, Trash2 } from 'lucide-react';


const ITEM_TYPES = {
  feed: 'Yem',
  medication: 'İlaç',
  vaccine: 'Aşı',
  equipment: 'Ekipman',
  supplies: 'Sarf Malzeme',
  other: 'Diğer'
};

export default function InventoryPage() {
  const { user } = useAuth();
  const farmId = user?.farm_id;

  const [items, setItems] = useState([]);
  const [lowStockItems, setLowStockItems] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [form, setForm] = useState({
    item_name: '',
    item_type: 'feed',
    unit: 'kg',
    quantity: '',
    reorder_level: '',
    unit_cost: '',
    supplier: '',
    notes: ''
  });

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const res = await inventoryService.list(farmId);
      const fetchedItems = res.data.data || [];
      setItems(fetchedItems);
      const lowStock = fetchedItems.filter(i => {
        const min = i.minimum_level ?? i.reorder_level;
        return min !== null && min !== undefined && parseFloat(i.quantity) <= parseFloat(min);
      });
      setLowStockItems(lowStock);
    } catch {
      toast.error('Envanter yüklenemedi');
    } finally {
      setLoading(false);
    }
  }, [farmId]);

  useEffect(() => {
    load();
  }, [load]);

  const handleAdd = async (e) => {
    e.preventDefault();
    if (!form.item_name || !form.quantity) {
      toast.error('İsim ve miktar zorunlu');
      return;
    }
    try {
      await inventoryService.create(farmId, form);
      toast.success('Envanter ürünü eklendi');
      setShowForm(false);
      setForm({
        item_name: '',
        item_type: 'feed',
        unit: 'kg',
        quantity: '',
        reorder_level: '',
        unit_cost: '',
        supplier: '',
        notes: ''
      });
      load();
    } catch {
      toast.error('İşlem başarısız');
    }
  };

  const handleUpdate = async (id, quantity) => {
    try {
      await inventoryService.update(farmId, id, { quantity });
      toast.success('Miktar güncellendi');
      load();
    } catch {
      toast.error('Güncelleme başarısız');
    }
  };

  const handleDelete = async (id) => {
    if (!window.confirm('Silmek istediğinizden emin misiniz?')) return;
    try {
      await inventoryService.delete(farmId, id);
      toast.success('Silindi');
      load();
    } catch {
      toast.error('Silinmedi');
    }
  };

  const totalValue = items.reduce((sum, i) => sum + (parseFloat(i.quantity || 0) * parseFloat(i.unit_cost || 0)), 0);

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-gray-900">📦 Envanter Yönetimi</h1>
          <p className="text-sm text-gray-500">Yem, ilaç ve ekipman stok takibi</p>
        </div>
        <button onClick={() => setShowForm(!showForm)} className={`btn-primary flex items-center justify-center gap-2 ${showForm ? 'bg-red-500 hover:bg-red-600' : ''}`}>
          {showForm ? 'İptal' : <><Plus className="w-4 h-4" /> Ürün Ekle</>}
        </button>
      </div>

      {/* Özet Kartları */}
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
        <div className="card text-center group hover:border-blue-200 transition-colors">
          <p className="text-gray-400 text-xs font-bold uppercase tracking-wider">Toplam Ürün</p>
          <p className="text-3xl font-black text-blue-700 mt-2">{items.length}</p>
        </div>
        <div className="card text-center group hover:border-red-200 transition-colors">
          <p className="text-gray-400 text-xs font-bold uppercase tracking-wider">Düşük Stok</p>
          <p className="text-3xl font-black text-red-700 mt-2">{lowStockItems.length}</p>
        </div>
        <div className="card text-center group hover:border-emerald-200 transition-colors">
          <p className="text-gray-400 text-xs font-bold uppercase tracking-wider">Toplam Değer</p>
          <p className="text-3xl font-black text-emerald-700 mt-2">₺{totalValue.toLocaleString('tr-TR', { minimumFractionDigits: 2 })}</p>
        </div>
      </div>

      {/* Düşük Stok Uyarısı */}
      {lowStockItems.length > 0 && (
        <div className="card bg-red-50/50 border-l-4 border-red-500 animate-pulse-slow">
          <div className="flex items-center gap-2 mb-3 text-red-700">
            <AlertTriangle className="w-5 h-5" />
            <h3 className="font-bold">Düşük Stok Uyarısı</h3>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-2">
            {lowStockItems.map(item => (
              <div key={item.id} className="text-sm text-red-800 bg-red-100/50 px-3 py-2 rounded-xl border border-red-200 flex justify-between">
                <span className="font-medium">{item.name || item.item_name}</span>
                <span className="font-black">{item.quantity} {item.unit}</span>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Form */}
      {showForm && (
        <div className="card border-blue-100 bg-blue-50/20 animate-in fade-in slide-in-from-top-4">
          <h2 className="text-lg font-bold mb-4 text-blue-900">Envanter Kaydı Oluştur</h2>
          <form onSubmit={handleAdd} className="space-y-4">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="md:col-span-2">
                <label className="block text-xs font-bold text-gray-400 uppercase mb-1 ml-1">Ürün Adı</label>
                <input
                  type="text"
                  placeholder="Örn: Besi Yemi, Şap Aşısı vb."
                  value={form.item_name}
                  onChange={e => setForm({ ...form, item_name: e.target.value })}
                  className="input-field"
                  required
                />
              </div>
              <div>
                <label className="block text-xs font-bold text-gray-400 uppercase mb-1 ml-1">Kategori</label>
                <select
                  value={form.item_type}
                  onChange={e => setForm({ ...form, item_type: e.target.value })}
                  className="input-field"
                >
                  {Object.entries(ITEM_TYPES).map(([k, v]) => (
                    <option key={k} value={k}>{v}</option>
                  ))}
                </select>
              </div>
              <div>
                <label className="block text-xs font-bold text-gray-400 uppercase mb-1 ml-1">Birim</label>
                <input
                  type="text"
                  placeholder="Örn: kg, Litre, Adet"
                  value={form.unit}
                  onChange={e => setForm({ ...form, unit: e.target.value })}
                  className="input-field"
                />
              </div>
              <div>
                <label className="block text-xs font-bold text-gray-400 uppercase mb-1 ml-1">Mevcut Miktar</label>
                <input
                  type="number"
                  step="0.01"
                  placeholder="0.00"
                  value={form.quantity}
                  onChange={e => setForm({ ...form, quantity: e.target.value })}
                  className="input-field"
                  required
                />
              </div>
              <div>
                <label className="block text-xs font-bold text-gray-400 uppercase mb-1 ml-1">Kritik Stok Seviyesi</label>
                <input
                  type="number"
                  step="0.01"
                  placeholder="Alt Sınır"
                  value={form.reorder_level}
                  onChange={e => setForm({ ...form, reorder_level: e.target.value })}
                  className="input-field"
                />
              </div>
              <div>
                <label className="block text-xs font-bold text-gray-400 uppercase mb-1 ml-1">Birim Maliyet (₺)</label>
                <input
                  type="number"
                  step="0.01"
                  placeholder="0.00"
                  value={form.unit_cost}
                  onChange={e => setForm({ ...form, unit_cost: e.target.value })}
                  className="input-field"
                />
              </div>
              <div>
                <label className="block text-xs font-bold text-gray-400 uppercase mb-1 ml-1">Tedarikçi</label>
                <input
                  type="text"
                  placeholder="Örn: X Tarım Ltd. Şti."
                  value={form.supplier}
                  onChange={e => setForm({ ...form, supplier: e.target.value })}
                  className="input-field"
                />
              </div>
            </div>
            <div>
              <label className="block text-xs font-bold text-gray-400 uppercase mb-1 ml-1">Notlar</label>
              <textarea
                placeholder="Ürün hakkında ek bilgiler..."
                value={form.notes}
                onChange={e => setForm({ ...form, notes: e.target.value })}
                className="input-field"
                rows={2}
              />
            </div>
            <div className="flex gap-3">
              <button type="button" onClick={() => setShowForm(false)} className="btn-secondary flex-1">Vazgeç</button>
              <button type="submit" className="btn-primary flex-1">Envantere Ekle</button>
            </div>
          </form>
        </div>
      )}

      {/* Envanter Listesi */}
      <div className="card p-0 overflow-hidden">
        <div className="overflow-x-auto">
          {loading ? (
            <div className="flex items-center justify-center py-12">
              <div className="w-8 h-8 border-4 border-blue-600 border-t-transparent rounded-full animate-spin" />
            </div>
          ) : items.length === 0 ? (
            <div className="text-center py-12 text-gray-400">
              <p className="text-4xl mb-2">📦</p>
              <p className="font-medium text-sm">Envanter listesi boş</p>
            </div>
          ) : (
            <table className="w-full text-sm">
              <thead className="bg-gray-50 border-b">
                <tr>
                  <th className="text-left px-6 py-4 font-bold text-gray-400 uppercase tracking-wider text-[10px]">Ürün</th>
                  <th className="text-left px-6 py-4 font-bold text-gray-400 uppercase tracking-wider text-[10px]">Tür</th>
                  <th className="text-center px-6 py-4 font-bold text-gray-400 uppercase tracking-wider text-[10px]">Mevcut Stok</th>
                  <th className="text-right px-6 py-4 font-bold text-gray-400 uppercase tracking-wider text-[10px]">Toplam Değer</th>
                  <th className="text-center px-6 py-4 font-bold text-gray-400 uppercase tracking-wider text-[10px]">İşlemler</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100">
                {items.map(item => {
                  const minStock = item.minimum_level ?? item.reorder_level;
                  const isLowStock = minStock !== null && minStock !== undefined && parseFloat(item.quantity) <= parseFloat(minStock);
                  const itemName = item.name || item.item_name;
                  return (
                    <tr key={item.id} className={`${isLowStock ? 'bg-red-50/50' : ''} hover:bg-gray-50 transition-colors group`}>
                      <td className="px-6 py-4">
                        <p className="font-bold text-gray-900">{itemName}</p>
                        <p className="text-[10px] text-gray-500 font-medium uppercase">{item.supplier_name || item.supplier || 'Bilinmeyen Tedarikçi'}</p>
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap font-medium text-gray-600">
                        {ITEM_TYPES[item.item_type] || item.item_type}
                      </td>
                      <td className="px-6 py-4 text-center whitespace-nowrap">
                        <span className={`inline-block px-3 py-1 rounded-full font-black text-xs ${isLowStock ? 'bg-red-100 text-red-700 border border-red-200' : 'bg-green-50 text-green-700 border border-green-100'}`}>
                          {item.quantity} {item.unit}
                        </span>
                      </td>
                      <td className="px-6 py-4 text-right font-black text-gray-900 whitespace-nowrap">
                        ₺{(parseFloat(item.quantity || 0) * parseFloat(item.unit_cost || 0)).toLocaleString('tr-TR', { minimumFractionDigits: 2 })}
                      </td>
                      <td className="px-6 py-4 text-center whitespace-nowrap">
                        <div className="flex items-center justify-center gap-2">
                          <button
                            onClick={() => {
                              const qty = prompt(`${itemName} - Yeni miktar:`, item.quantity);
                              if (qty !== null && qty !== '') handleUpdate(item.id, qty);
                            }}
                            className="p-2 text-blue-600 hover:bg-blue-100 rounded-xl transition-colors"
                            title="Miktarı Güncelle"
                          >
                            <Edit3 className="w-4 h-4" />
                          </button>
                          <button
                            onClick={() => handleDelete(item.id)}
                            className="p-2 text-red-600 hover:bg-red-100 rounded-xl transition-colors"
                            title="Sil"
                          >
                            <Trash2 className="w-4 h-4" />
                          </button>
                        </div>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          )}
        </div>
      </div>
    </div>
  );
}
